package pkg

import (
	"archive/tar"
	"archive/zip"
	"compress/gzip"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// ExtractArchive extracts a .tar.gz, .tgz, .tar, or .zip archive into destDir.
// It automatically detects and strips any single top-level root directory
// (such as those generated by GitHub release tarballs) and protects against
// directory traversal (Zip Slip).
func ExtractArchive(archivePath, destDir string) error {
	lower := strings.ToLower(archivePath)
	if strings.HasSuffix(lower, ".tar.gz") || strings.HasSuffix(lower, ".tgz") {
		return ExtractTarGz(archivePath, destDir)
	}
	if strings.HasSuffix(lower, ".tar") {
		f, err := os.Open(archivePath)
		if err != nil {
			return err
		}
		defer f.Close()
		return extractTarReader(tar.NewReader(f), destDir)
	}
	if strings.HasSuffix(lower, ".zip") {
		return ExtractZip(archivePath, destDir)
	}
	return fmt.Errorf("unsupported archive format: %s", archivePath)
}

// ExtractTarGz extracts a gzip-compressed tar archive into destDir.
func ExtractTarGz(tarGzPath, destDir string) error {
	f, err := os.Open(tarGzPath)
	if err != nil {
		return fmt.Errorf("failed to open archive '%s': %w", tarGzPath, err)
	}
	defer f.Close()

	gzr, err := gzip.NewReader(f)
	if err != nil {
		return fmt.Errorf("failed to initialize gzip reader: %w", err)
	}
	defer gzr.Close()

	return extractTarReader(tar.NewReader(gzr), destDir)
}

// extractTarReader extracts entries from a tar.Reader into destDir.
// In the first pass, it inspects entries to determine if all entries share
// a common top-level directory (e.g., github-user-repo-sha/), and strips it.
func extractTarReader(tr *tar.Reader, destDir string) error {
	cleanDest := filepath.Clean(destDir)
	if err := os.MkdirAll(cleanDest, 0755); err != nil {
		return err
	}

	type cachedEntry struct {
		header *tar.Header
		data   []byte
	}

	var entries []cachedEntry
	rootDirs := make(map[string]bool)

	for {
		hdr, err := tr.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return fmt.Errorf("error reading tar archive: %w", err)
		}

		cleanName := filepath.Clean(hdr.Name)
		if cleanName == "." || cleanName == "/" {
			continue
		}

		parts := strings.Split(filepath.ToSlash(cleanName), "/")
		if len(parts) > 0 && parts[0] != "" && parts[0] != "." {
			rootDirs[parts[0]] = true
		}

		var data []byte
		if hdr.Typeflag == tar.TypeReg || hdr.Typeflag == tar.TypeRegA {
			data, err = io.ReadAll(tr)
			if err != nil {
				return fmt.Errorf("failed reading tar entry '%s': %w", hdr.Name, err)
			}
		}

		entries = append(entries, cachedEntry{
			header: hdr,
			data:   data,
		})
	}

	// Determine if there is a common single root prefix to strip
	stripPrefix := ""
	if len(rootDirs) == 1 {
		for root := range rootDirs {
			stripPrefix = root
		}
	}

	for _, entry := range entries {
		rel := filepath.Clean(entry.header.Name)
		if stripPrefix != "" {
			if rel == stripPrefix {
				continue
			}
			rel = strings.TrimPrefix(rel, stripPrefix)
			rel = strings.TrimPrefix(rel, string(filepath.Separator))
			rel = strings.TrimPrefix(rel, "/")
		}
		if rel == "" || rel == "." {
			continue
		}

		targetPath := filepath.Join(cleanDest, rel)
		// Zip slip check
		if !strings.HasPrefix(targetPath, cleanDest+string(filepath.Separator)) && targetPath != cleanDest {
			return fmt.Errorf("archive entry path escapes destination: %s", entry.header.Name)
		}

		switch entry.header.Typeflag {
		case tar.TypeDir:
			if err := os.MkdirAll(targetPath, 0755); err != nil {
				return err
			}
		case tar.TypeReg, tar.TypeRegA:
			if err := os.MkdirAll(filepath.Dir(targetPath), 0755); err != nil {
				return err
			}
			mode := entry.header.FileInfo().Mode()
			perm := os.FileMode(0644)
			if mode&0111 != 0 {
				perm = 0755
			}
			if err := os.WriteFile(targetPath, entry.data, perm); err != nil {
				return fmt.Errorf("failed writing '%s': %w", targetPath, err)
			}
		}
	}

	return nil
}

// ExtractZip extracts a zip archive into destDir with Zip Slip protection
// and automatic single root directory prefix stripping.
func ExtractZip(zipPath, destDir string) error {
	cleanDest := filepath.Clean(destDir)
	if err := os.MkdirAll(cleanDest, 0755); err != nil {
		return err
	}

	zr, err := zip.OpenReader(zipPath)
	if err != nil {
		return fmt.Errorf("failed to open zip file '%s': %w", zipPath, err)
	}
	defer zr.Close()

	rootDirs := make(map[string]bool)
	for _, f := range zr.File {
		cleanName := filepath.Clean(f.Name)
		parts := strings.Split(filepath.ToSlash(cleanName), "/")
		if len(parts) > 0 && parts[0] != "" && parts[0] != "." {
			rootDirs[parts[0]] = true
		}
	}

	stripPrefix := ""
	if len(rootDirs) == 1 {
		for root := range rootDirs {
			stripPrefix = root
		}
	}

	for _, f := range zr.File {
		rel := filepath.Clean(f.Name)
		if stripPrefix != "" {
			if rel == stripPrefix {
				continue
			}
			rel = strings.TrimPrefix(rel, stripPrefix)
			rel = strings.TrimPrefix(rel, string(filepath.Separator))
			rel = strings.TrimPrefix(rel, "/")
		}
		if rel == "" || rel == "." {
			continue
		}

		targetPath := filepath.Join(cleanDest, rel)
		if !strings.HasPrefix(targetPath, cleanDest+string(filepath.Separator)) && targetPath != cleanDest {
			return fmt.Errorf("zip entry path escapes destination: %s", f.Name)
		}

		if f.FileInfo().IsDir() {
			if err := os.MkdirAll(targetPath, 0755); err != nil {
				return err
			}
			continue
		}

		if err := os.MkdirAll(filepath.Dir(targetPath), 0755); err != nil {
			return err
		}

		rc, err := f.Open()
		if err != nil {
			return fmt.Errorf("failed to open zip entry '%s': %w", f.Name, err)
		}

		mode := f.FileInfo().Mode()
		perm := os.FileMode(0644)
		if mode&0111 != 0 {
			perm = 0755
		}

		outFile, err := os.OpenFile(targetPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, perm)
		if err != nil {
			rc.Close()
			return err
		}

		_, err = io.Copy(outFile, rc)
		outFile.Close()
		rc.Close()
		if err != nil {
			return fmt.Errorf("failed writing zip entry '%s': %w", targetPath, err)
		}
	}

	return nil
}

// CreateTarGz creates a .tar.gz archive at destTarGzPath containing all files
// and subdirectories under sourceDir.
func CreateTarGz(sourceDir, destTarGzPath string) error {
	cleanSource := filepath.Clean(sourceDir)
	if err := os.MkdirAll(filepath.Dir(destTarGzPath), 0755); err != nil {
		return err
	}

	outFile, err := os.Create(destTarGzPath)
	if err != nil {
		return fmt.Errorf("failed to create archive '%s': %w", destTarGzPath, err)
	}
	defer outFile.Close()

	gzw := gzip.NewWriter(outFile)
	defer gzw.Close()

	tw := tar.NewWriter(gzw)
	defer tw.Close()

	return filepath.Walk(cleanSource, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		rel, err := filepath.Rel(cleanSource, path)
		if err != nil {
			return err
		}
		if rel == "." {
			return nil
		}

		relSlash := filepath.ToSlash(rel)
		hdr, err := tar.FileInfoHeader(info, info.Name())
		if err != nil {
			return err
		}
		hdr.Name = relSlash

		if err := tw.WriteHeader(hdr); err != nil {
			return err
		}

		if info.IsDir() {
			return nil
		}

		f, err := os.Open(path)
		if err != nil {
			return err
		}
		defer f.Close()

		_, err = io.Copy(tw, f)
		return err
	})
}

// TestArchiveIntegrity verifies that archivePath exists, has non-zero size,
// and can be decompressed and read without unexpected EOF or checksum errors.
func TestArchiveIntegrity(archivePath string, formatHint ...string) error {
	fi, err := os.Stat(archivePath)
	if err != nil {
		return err
	}
	if fi.Size() == 0 {
		return fmt.Errorf("archive file is empty (0 bytes)")
	}

	hint := ""
	if len(formatHint) > 0 {
		hint = strings.ToLower(formatHint[0])
	}
	lower := strings.ToLower(archivePath)

	f, err := os.Open(archivePath)
	if err != nil {
		return err
	}
	defer f.Close()

	var header [4]byte
	n, _ := io.ReadFull(f, header[:])
	_, _ = f.Seek(0, 0)

	isGzip := n >= 2 && header[0] == 0x1f && header[1] == 0x8b
	isZip := n >= 4 && header[0] == 0x50 && header[1] == 0x4b && header[2] == 0x03 && header[3] == 0x04

	if isGzip || strings.HasSuffix(lower, ".tar.gz") || strings.HasSuffix(lower, ".tgz") || strings.HasSuffix(hint, ".tar.gz") || strings.HasSuffix(hint, ".tgz") {
		gzr, err := gzip.NewReader(f)
		if err != nil {
			return fmt.Errorf("invalid gzip header: %w", err)
		}
		defer gzr.Close()

		tr := tar.NewReader(gzr)
		count := 0
		for {
			hdr, err := tr.Next()
			if err == io.EOF {
				break
			}
			if err != nil {
				return fmt.Errorf("corrupted tar entry: %w", err)
			}
			if hdr.Typeflag == tar.TypeReg || hdr.Typeflag == tar.TypeRegA {
				if _, err := io.Copy(io.Discard, tr); err != nil {
					return fmt.Errorf("truncated tar entry content: %w", err)
				}
			}
			count++
		}
		if count == 0 {
			return fmt.Errorf("archive contains no entries")
		}
		return nil
	}

	if isZip || strings.HasSuffix(lower, ".zip") || strings.HasSuffix(hint, ".zip") {
		_ = f.Close()
		zr, err := zip.OpenReader(archivePath)
		if err != nil {
			return fmt.Errorf("corrupted zip archive: %w", err)
		}
		defer zr.Close()

		if len(zr.File) == 0 {
			return fmt.Errorf("zip archive contains no entries")
		}
		for _, zf := range zr.File {
			rc, err := zf.Open()
			if err != nil {
				return fmt.Errorf("failed opening zip entry '%s': %w", zf.Name, err)
			}
			_, err = io.Copy(io.Discard, rc)
			_ = rc.Close()
			if err != nil {
				return fmt.Errorf("truncated zip entry content for '%s': %w", zf.Name, err)
			}
		}
		return nil
	}

	return fmt.Errorf("unsupported archive format: %s", archivePath)
}
